float sWarp, sTwist;
vec3 g_p;

float map(vec3 p) {   

   float z = p.z-move();
   float len =  length(p.xy);

   p.xy *= rot(.1*z*sin(tt)*sTwist-.5*PI*sin(tt)*sTwist);

   // p.zy += vec2(.2, .1)*sin(.2*tt+len*1.);
   p.xy *= mix(1., mix(1.2, .9, sin(len*1. +.5*tt)), sWarp);

   vec3 bp = p;

   float d = 1e9;
   float ds = 1e9;

   // seats
   p.z = pMod(p.z, 4.2);


   p.x = abs(p.x) - 2.4;
   p.x = abs(p.x) - .78;
   g_p = p;


   // upper seat
   d = box(p, vec3(.7, 1, .12+.1*SIN(-(p.y-.75)*2.))+.1*(-sabsk(p.x, .2))) - .12;

   p.y += 1.;
   p.yz = p.zy;

   // lower seat
   float d2 = box(p, vec3(.7, 1.2, .1+.1*SIN(-(p.y-.75)*2.))+.1*(-sabsk(p.x, .2))) - .12;

   d = min(d, d2);

   g_mat = 0.;
   p = bp;

   // floor 
   float f = abs(p.y-4.);

   f = min(f, p.y+2.);

   // ceiling
   p.x = abs(p.x)-5.;

   float fs = (p.x);
   p.z += 2.4;
   p.z = pMod(p.z, 4.2);

   p.y -= 1.;

   // windows
   float w = box(p, vec3(100, 1.1, 1.)) -.2;

   fs = max(-fs, -(w));
   f = min(f, fs);

   g_mat = f < d ? 1. : g_mat;
   g_p = f < d ? p : g_p;


   d = min(d, f);
   g_mat = w < d ? 4. : g_mat;
   g_p = w < d ? p : g_p;

   p = bp;
   p.z = pMod(p.z, 4.);
   p.y -= 2.9;
   p.x = abs(p.x) - 2.5;

   p.z += 1.;
   p.yz = p.zy;

   // light
   float g = sdCapsule(p, 2.1, 0.02);

   g_glow += .2/(20.+ pow(abs(g)*1.1, 6.))*(exp(-(bp.z-move())*.09));

   g_mat = g < d ? 2. : g_mat;
   g_p = g < d ? p : g_p;  

   d = min(d, g);

   return d*.5;

}


vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}


// iq's shadow function
float softshadow( in vec3 ro, in vec3 rd, float mint, float maxt, float k ) {

    float res = 1.0;
    float ph = 1e20;
    for( float t=mint; t<maxt; )
    {
        float h = map(ro + rd*t);
        if( h<0.001 )
            return 0.0;
        float y = h*h/(2.0*ph);
        float d = sqrt(h*h-y*y);
        res = min( res, k*d/max(0.0,t-y) );
        ph = h;
        t += h;
    }
    return res;
}


// why not put the raymarcher in a separate function (;
vec3 raymarch(vec3 ro, vec3 rd, float steps) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;
    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        mat = g_mat;  // save global material

        if(abs(d) < 0.0001 || t > 100.) break;

        t += d;
        p += rd*d;
    }


    return vec3(t, mat, t);
}




// from iq code
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}



vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {

    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}

