// Zucconi's spectral palette
vec3 spectral_zucconi6(float x) {
    x = fract(x);
    const vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
    const vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
    const vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);
    const vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
    const vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
    const vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);
    return bump3y(c1 * (x - x1), y1) + bump3y(c2 * (x - x2), y2) ;
}


// spectral palette by wavelength
vec3 waveSpectrum(float w){

    if(w > 700.0 || w < 400.0){
        return vec3(0);
    }

	float x = fract((w - 400.0)/ 300.0);

	vec3 col = spectral_zucconi6(x);

    // Undo gamma
    col = invGamma(col);

    return col;
}


// physical based diffraction grating
vec3 diffraction(vec3 rd, vec3 n, vec3 td, vec3 l, float d) {

    vec3 col = vec3(0);

    float cos_ThetaL = dot(l, td);
    float cos_ThetaV = dot(rd, td);

    float u = abs(cos_ThetaL - cos_ThetaV);

    if(u == 0.) {
        return vec3(0);
    }

    for(float i=1.; i < 2.; i++) {
        float wavelength = u * d / i;
        col += waveSpectrum(wavelength);
    }
    col = clamp(col, vec3(0), vec3(1));
    return col;
}


float smoothNoise21(vec2 p) {
    // Calculate integer and fractional coordinates
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Compute gradients at the four corners of the cell
    float n00 = dot(vec2(cos(dot(i, vec2(127.1, 311.7))), sin(dot(i, vec2(127.1, 311.7)))), f - vec2(0.0, 0.0));
    float n01 = dot(vec2(cos(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7)))), f - vec2(0.0, 1.0));
    float n10 = dot(vec2(cos(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7)))), f - vec2(1.0, 0.0));
    float n11 = dot(vec2(cos(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7)))), f - vec2(1.0, 1.0));

    // Smooth interpolation using Hermite curve (smoothstep)
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Bilinear interpolation with gradients
    return mix(mix(n00, n10, u.x), mix(n01, n11, u.x), u.y);
}

// Cirquit maze pattern
// 
// Pretty much taken as is from https://www.shadertoy.com/view/Wds3z7
// by shadertoy user srtuss


// Some more interesting seeds 19.41, 19.24, 19.19, 20.54, 24.53441
#define PATTERN_SEED 19.41

float k = .1;
#define K2 ((1. - k) / 2.)
#define K3 (sqrt(2.) * .5 - K2)
#define R iResolution

float tile0(vec2 uv)
{
    float v = length(uv) - K3;
    float w = K2 - length(vec2(abs(uv.x) - .5, uv.y - .5));
    return v = mix(v, w,
                   //smoothstep(.1, -.1, abs(uv.x) - uv.y)
                   step(abs(uv.x), uv.y)
                  );
}

float tile1(vec2 uv)
{
    return abs(length(uv - .5) - .5) - k * .5;
}

float tile2(vec2 uv)
{
    return abs(uv.x) - k * .5;
}

float tile3(vec2 uv)
{
    return max(-uv.x - k * .5, K2 - length(vec2(uv.x - .5, abs(uv.y) - .5)));
}

float tile4(vec2 uv)
{
    return K2 - length(vec2(abs(uv.x) - .5, abs(uv.y) - .5));
}

float tile(vec2 uv, int tile)
{

    switch(tile)
    {
        case 0: return 1.414;
        case 1: return max(tile0(uv), .15 - length(uv));
        case 2: return tile0(uv.yx);
        case 3: return tile1(uv);
        case 4: return tile0(vec2(uv.x, -uv.y));
        case 5: return tile2(uv);
        case 6: return tile1(vec2(uv.x, -uv.y));
        case 7: return tile3(uv);
        case 8: return tile0(vec2(uv.y, -uv.x));
        case 9: return tile1(vec2(-uv.x, uv.y));
        case 10: return tile2(uv.yx);
        case 11: return tile3(uv.yx);
        case 12: return tile1(vec2(-uv.x, -uv.y));
        case 13: return tile3(vec2(-uv.x, uv.y));
        case 14: return tile3(vec2(-uv.y, uv.x));
        case 15: return tile4(uv);
    }
}

// "Hash without Sine" - borrowed from Dave Hoskins's shader
// https://www.shadertoy.com/view/4djSRW
#define HASHSCALE1 .1031
float hash(vec2 p)
{   

	vec3 p3  = fract(vec3(p.xyx) * HASHSCALE1);
    p3 += dot(p3, p3.yzx + PATTERN_SEED);
    return fract((p3.x + p3.y) * p3.z);
}

float map(vec2 uv)
{
    int b = 0;
    uv += .5;
    vec2 id = floor(uv);
    if(hash(id) >= .5)
        b += 1;
    if(hash(-id) >= .5)
        b += 8;
    if(hash(id - vec2(0., 1.)) >= .5)
        b += 4;
    if(hash(-(id + vec2(1., 0.))) >= .5)
        b += 2;

    return tile(fract(uv) - .5, b);
}

vec2 rotate(vec2 uv, float a)
{
    float co = cos(a);
    float si = sin(a);
    return uv * mat2(co, si, -si, co);
}

float height(vec2 uv)
{
    float r = map(uv) - .1;
    return sqrt(.01 - min(r * r, .01));
}

